package io.ottl.quarkus.deployment;

import io.quarkus.gizmo.BytecodeCreator;
import io.quarkus.gizmo.FieldDescriptor;
import io.quarkus.gizmo.MethodDescriptor;
import io.quarkus.gizmo.ResultHandle;

/**
 * Shared Gizmo snippets for boxing, unboxing and {@code Class} constants. Primitive {@link Class}
 * literals are the wrapper {@code TYPE} field so the generated bytecode stays reflection-free.
 */
final class BytecodeSupport {

    private BytecodeSupport() {
    }

    static ResultHandle box(BytecodeCreator bc, ResultHandle value, Class<?> type) {
        if (!type.isPrimitive()) {
            return value;
        }
        Class<?> wrapper = wrapper(type);
        return bc.invokeStaticMethod(MethodDescriptor.ofMethod(wrapper, "valueOf", wrapper, type), value);
    }

    static ResultHandle convertArg(BytecodeCreator bc, ResultHandle coerced, Class<?> type) {
        if (!type.isPrimitive()) {
            return bc.checkCast(coerced, type);
        }
        Class<?> wrapper = wrapper(type);
        ResultHandle boxed = bc.checkCast(coerced, wrapper);
        return bc.invokeVirtualMethod(MethodDescriptor.ofMethod(wrapper, type.getName() + "Value", type), boxed);
    }

    static ResultHandle loadClassConstant(BytecodeCreator bc, Class<?> type) {
        if (!type.isPrimitive()) {
            return bc.loadClass(type);
        }
        return bc.readStaticField(FieldDescriptor.of(wrapper(type), "TYPE", Class.class));
    }

    private static Class<?> wrapper(Class<?> primitive) {
        if (primitive == boolean.class) return Boolean.class;
        if (primitive == int.class) return Integer.class;
        if (primitive == long.class) return Long.class;
        if (primitive == double.class) return Double.class;
        if (primitive == float.class) return Float.class;
        if (primitive == short.class) return Short.class;
        if (primitive == byte.class) return Byte.class;
        if (primitive == char.class) return Character.class;
        throw new IllegalArgumentException("Not a primitive: " + primitive);
    }
}
